"""Join independently accepted results for presentation; never estimate or select cuts."""
from pathlib import Path
import argparse,json
import pandas as pd
from new_adapter import path,sha

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--output',required=True);a=ap.parse_args();out=path(a.output);assert not out.exists();pins={str(Path(__file__)):sha(Path(__file__))};tables=[];gates=[];index=[];cohort_checks=[];fit_count=0;interval_count=0
 batches=[('060','supported_end_forest','cycle07_newsource060_regression_independent','cycle07_newsource060_figures_v2','new060_figure_visual_admission_v2.json'),('120','supported_end_forest','cycle07_newsource120_regression_independent','cycle07_newsource120_figures_v1','new120_figure_visual_admission_v1.json'),('030045090','supported_end_forest','cycle07_newsource030045090_regression_independent','cycle07_newsource030045090_figures_v2','new030045090_figure_visual_admission_v2.json'),('_empirical','empirically_retained_candidate_partition','cycle07_newsource_empirical_regression_independent','cycle07_newsource_empirical_figures_v1','new_empirical_figure_visual_admission_v1.json')]
 registry=path('model/cycle07_scale_hierarchy/empirical_registry_source477_v1/registry_receipt.json');rr=json.loads(registry.read_text());registry_table=registry.parent/'empirical_level_registry.csv';assert sha(registry_table)==rr['files'][registry_table.name];mapping=pd.read_csv(registry_table).set_index('candidate_cap').empirical_level.to_dict()
 for p in [registry,registry_table,path('reviews/cycle07_empirical_registry_independent/audit.json')]:pins[str(p)]=sha(p)
 for tag,family,review,figures,visual in batches:
  src=path(f'analysis/cycle07_newsource{tag}_baseline_v1');receipt=src/'run_receipt.json';r=json.loads(receipt.read_text());assert r['source_inputs_unchanged']is True;fit_count+=r['n_fits'];interval_count+=r['n_bootstrap_intervals']
  for name in ['audit.json','spatial_audit.json']:
   p=path('reviews/'+review)/name;ad=json.loads(p.read_text());assert ad['all_checks_passed']is True and sha(receipt)in p.read_text();pins[str(p)]=sha(p)
  vp=path('reviews/cycle07_controller_independent')/visual;assert sha(path('analysis/'+figures)/'receipt.json')in vp.read_text();assert json.loads(vp.read_text())['all_checks_passed']is True;pins[str(vp)]=sha(vp)
  for p in [receipt,src/'preregistration.json',src/'model_metrics.csv',src/'sample_gates.csv',src/'common_sample_membership.parquet',path('analysis/'+figures)/'receipt.json']:pins[str(p)]=sha(p)
  reg=json.loads((src/'preregistration.json').read_text());source=Path(reg['source_receipt']);assert sha(source)==reg['source_receipt_sha256'];pins[str(source)]=sha(source)
  d=pd.read_csv(src/'model_metrics.csv');g=pd.read_csv(src/'sample_gates.csv');members=pd.read_parquet(src/'common_sample_membership.parquet')
  for cap in sorted(d.candidate_cap.unique()):
   level=int(mapping[cap])if family=='empirically_retained_candidate_partition'else None;index.append({'analysis_view_family':family,'candidate_cap':int(cap),'spatial_resolution_index':level,'functional_order_observed':False,'actual_result_directory':str(src),'figure_directory':str(path('analysis/'+figures))})
   for f in ['A_M1_M2','B_M1_M2_M3_inventory']:
    whole=set(members[(members.candidate_cap==cap)&(members.scenario==f+'__primary')].unit_id);rural=set(members[(members.candidate_cap==cap)&(members.scenario==f+'__rural_population_sensitivity')].unit_id);assert whole==rural;cohort_checks.append({'analysis_view_family':family,'candidate_cap':int(cap),'comparison_family':f,'whole_rural_actual_unit_id_sets_equal':True,'n':len(whole)})
  for t in [d,g]:t['analysis_view_family']=family;t['spatial_resolution_index']=pd.array(t.candidate_cap.map(mapping)if family=='empirically_retained_candidate_partition'else[None]*len(t),dtype='Int64')
  tables.append(d);gates.append(g)
 d=pd.concat(tables,ignore_index=True);g=pd.concat(gates,ignore_index=True);assert len(index)==9 and len(d)==fit_count==177 and len(g)==108 and interval_count==1307;assert not d.duplicated(['analysis_view_family','candidate_cap','scenario','model']).any();z=d[d.scenario.str.endswith('__primary')|d.scenario.str.endswith('__rural_population_sensitivity')];assert len(z)==90
 out.mkdir(parents=True);d.to_csv(out/'all177_reviewed_model_metrics.csv',index=False);g.to_csv(out/'all108_reviewed_sample_gates.csv',index=False);z.to_csv(out/'all90_primary_whole_and_rural_results.csv',index=False);pd.DataFrame(index).to_csv(out/'nine_analysis_views.csv',index=False)
 limits=['Five operational supported-end forests and four empirically retained candidate partitions are separate families.','Spatial resolution indices0–3 are not observed functional orders, service-capacity tiers or demographic types.','All models are descriptive and conditional on source values; Mi2021 is fixed relative to assignment but not temporally exogenous to2010–2021 growth.','Whole and rural outcomes have exactly the same actual unit-ID cohort within each of18view×family comparisons; different A/B families and different views have different cohorts.','Pure-primary and supported-primary2010 sensitivity gates fail in every view; national primary-only verification remains unavailable.','Source inventory HHI and comparable seed counts do not prove functional polycentricity; residual spatial dependence remains.','Influential small-baseline percentage outcomes were retained without tuning, winsorization or cut selection by regression score.','Unknown source values, out-of-horizon travel and unobserved capacities are not absence or zero.']
 text='Все девять аналитических представлений реально рассчитаны и независимо приняты по источникам, численной математике, пространственной диагностике и итоговым рисункам. Всего 177 моделей, 108 проверок допустимости выборки и 1307 бутстреп-интервалов; это не 177 независимых наблюдений или испытаний.\n\nПять конечных лесов при пределах 30/45/60/90/120 минут и четыре эмпирически сохранённых разбиения при пределах 45/60/90/120 минут сохранены отдельными семьями. Индексы пространственного разрешения 0–3 не означают наблюдаемые функциональные порядки центров.\n\nСводные численные таблицы находятся рядом. Подробная интерпретация: ../cycle07_supported_forests_numeric_summary_v1/interpretation_ru.md и ../cycle07_empirical_numeric_summary_v1/interpretation_ru.md. Для сельской зоны сохранён отдельный исход на той же фактической выборке; выводы о всей зоне не подменяют выводы о сельской части.\n\nЭто приёмка конкретного аналитического блока, а не заявление о полном завершении исследования или доказательстве всей концепции Word. Ограничения первичных данных 2010, наблюдаемой сети услуг, мощностей и функциональной иерархии остаются явными.\n';(out/'interpretation_ru.md').write_text(text)
 for p,h in pins.items():assert sha(Path(p))==h
 handoff={'status':'ALL_NINE_ACTUAL_ANALYSIS_VIEWS_INDEPENDENTLY_ACCEPTED_SOURCE_NUMERICS_SPATIAL_FINAL_FIGURES','actual_fits':177,'sample_gates':108,'computed_sample_gates':int(g.status.eq('COMPUTED').sum()),'gated_not_estimated':int(g.status.ne('COMPUTED').sum()),'bootstrap_intervals':1307,'views':index,'actual_whole_rural_cohort_identity_checks':cohort_checks,'material_limits':limits,'files_sha256':pins,'derived_outputs_sha256':{p.name:sha(p)for p in out.iterdir()}};(out/'handoff.json').write_text(json.dumps(handoff,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'handoff_sha256':sha(out/'handoff.json'),'views':9,'fits':177}))
if __name__=='__main__':main()
